//! Linux errno names and texts, generated by build.rs from the asm-generic errno headers.

include!(concat!(env!("OUT_DIR"), "/errno.rs"));

/// Kernel-internal restart codes a recording shows when a signal interrupts a syscall.
const RESTART_TEXT: &str = "interrupted by a signal (kernel-internal code; the program sees EINTR or the call is restarted)";
const RESTART_CODES: [(i64, &str); 4] =
    [(512, "ERESTARTSYS"), (513, "ERESTARTNOINTR"), (514, "ERESTARTNOHAND"), (516, "ERESTART_RESTARTBLOCK")];

/// `(name, text)` of errno `n` (positive), e.g. `(ENOENT, No such file or directory)`.
pub fn lookup(n: i64) -> Option<(&'static str, &'static str)> {
    if let Ok(i) = ERRNO_NAMES.binary_search_by_key(&n, |&(nr, ..)| nr) {
        let (_, name, text) = ERRNO_NAMES[i];
        return Some((name, text));
    }
    RESTART_CODES.iter().find(|&&(nr, _)| nr == n).map(|&(_, name)| (name, RESTART_TEXT))
}

#[cfg(test)]
mod tests {
    use super::lookup;

    #[test]
    fn header_codes_have_names_and_texts() {
        assert_eq!(lookup(2), Some(("ENOENT", "No such file or directory")));
        assert_eq!(lookup(11).map(|(name, _)| name), Some("EAGAIN"));
        assert_eq!(lookup(1), Some(("EPERM", "Operation not permitted")));
    }

    #[test]
    fn restart_codes_are_kernel_internal() {
        let (name, text) = lookup(512).unwrap();
        assert_eq!(name, "ERESTARTSYS");
        assert!(text.contains("kernel-internal"), "{text}");
        assert_eq!(lookup(516).map(|(name, _)| name), Some("ERESTART_RESTARTBLOCK"));
        assert_eq!(lookup(515), None);
    }

    #[test]
    fn unknown_numbers_have_no_name() {
        assert_eq!(lookup(0), None);
        assert_eq!(lookup(99999), None);
        assert_eq!(lookup(-2), None);
    }
}
